# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

from collections import deque

def averageOfLevels(self, root: TreeNode) -> list[float]:
    result = []
    if root is None:
        return result
    queue = deque([root])
    while queue:
        size = len(queue)                  # freeze this level's width
        level_sum = 0                       # Python ints never overflow
        for _ in range(size):
            node = queue.popleft()
            level_sum += node.val
            if node.left is not None:
                queue.append(node.left)
            if node.right is not None:
                queue.append(node.right)
        result.append(level_sum / size)     # average of this level
    return result

